"""Apply bounded proposed-design corrections; never connects to a database."""
from pathlib import Path
ROOT = Path(__file__).resolve().parents[4]
P = ROOT/'docs/design/physical'
def edit(name, replacements, append=''):
    p=P/name
    s=p.read_text(encoding='utf-8')
    for old,new in replacements:
        assert old in s,(name,old[:80])
        s=s.replace(old,new)
    p.write_text(s+append,encoding='utf-8')

